164		// Hidden measurement harness for the history retrieval layer (the facts
165		// analog lives under `facts eval`/`eval-gen`; summaries are compatible with
166		// `facts eval-compare`). Developer tooling, not agent surface.
167		addHidden(newHistoryEvalGenCommand(opts))
168		addHidden(newHistoryEvalCommand(opts))
169	
170		// Hidden agent-harness hook surface (Phase 2 item 2): wired into hooks by
171		// the harness (Claude Code, Entire CLI), not invoked by humans or agents.
172		addHidden(newHookCommand(opts))
173	
174		cmd.SetHelpCommandGroupID("misc")
175		setRootUsage(cmd, helpCommands)
