// assert against the exact stored value.
func fakeBaseURL(t *testing.T, fake *hostedFake) string {
	t.Helper()
	// The harness binds the fake server's URL; reading it back avoids plumbing
	// the httptest server through every helper return.
	return lastBoundBaseURL
}

